dir:








































































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',')
	select @@fields into #t from r11 a @@join
	  where a.id in (select id from #id)
	  order by a.line, a.id

	select id_dh, line_dh, sum(a.so_luong) as sl_bao_gia into #sl from r21 a with(index(id_dh)) where id <> @id and id_dh <> 0 and exists(select 1 from #t b where a.id_dh = b.id_dh and a.line_dh = b.line_dh) group by id_dh, line_dh
	update #t set sl_cl = a.so_luong - isnull(b.sl_bao_gia, 0) from #t a left join #sl b on a.id_dh = b.id_dh and a.line_dh = b.line_dh
	--update #t set so_luong0 = sl_cl
	select * from #t where sl_cl <> 0

	--DECLARE @ds_cong VARCHAR(4000)  
	--SELECT distinct ma_cong into #tt FROM #t a where a.id in (select id from #id)
	--DELETE #tt where ma_cong not in (select ma_cong from #t where so_luong0 <> 0)
	--SELECT @ds_cong = COALESCE(@ds_cong + ', ','') + ltrim(rtrim(ma_cong)) FROM #tt


	select a.ma_noi_di,a.ma_noi_den,a.ma_kh,a.ma_hang,a.ma_nt,b.ten_noi_di,c.ten_noi_den,d.ten_kh,e.ten_kh ten_hang,a.ngay_hl, a.ngay_hld, a.ma_gd, id id_dh from t11 a 
	  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
	  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
	  left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang = e.ma_kh
	where a.id in (select top 1 id from #id order by id desc) 

	drop table #id, #t, #sl









  &DefaultButton;




function filter$t21DC1Select(p){
  this.constructor(p);
}
filter$t21DC1Select.prototype = new DirEvent();
filter$t21DC1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$t21DC1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den','ma_kh','ten_kh', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,p.options._ma_kh, p.options._ten_kh,  p.options._ma_nt, p.options._unit_id]);
	dir$t21DC1SetMaster(p);

}

function dir$t21DC1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$t21DC1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = dt.findRow("[so_luong0] > [sl_cl]");

  var fun = function(){
    dt.removeRow('[so_luong0] == 0'); 
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong0');
    pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
	p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();

    return false;
}









					select top 1 a.ma_kh as [!ma_kh],d.ten_kh as [!ten_kh],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den],
					b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den], e.ten_kh as [!ten_hang],a.so_ct as [!so_ct]
					from t11 a left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang =e.ma_kh
					where a.id = @id
